const DEFAULT_THREADS = [512, 512, 1];
export const WARNINGS = [];

const UNIFORM_ALIGN = 256; // minStorageBufferOffsetAlignment upper bound
const BUFFER_ALIGN = 256;
const MAX_GROUPS = 65535;
const TYPED = { f32: Float32Array, i32: Int32Array, u32: Uint32Array };

const alignUp = (n, a) => Math.ceil(n / a) * a;

function fromBase64(text) {
  const bin = atob(text);
  const out = new Uint8Array(alignUp(bin.length, 4));
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function asBytes(name, data) {
  if (data instanceof ArrayBuffer) return new Uint8Array(data);
  if (ArrayBuffer.isView(data)) return new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
  throw new TypeError(`'${name}' must be an ArrayBuffer or a typed array`);
}

function padded(bytes) {
  if (bytes.byteLength % 4 === 0) return bytes;
  const out = new Uint8Array(alignUp(bytes.byteLength, 4));
  out.set(bytes);
  return out;
}

function normalizeThreads(threads) {
  if (threads == null) throw new Error('no dispatch size: pass { threads } to evaluate() or export with threads=...');
  const t = typeof threads === 'number' ? [threads] : Array.from(threads);
  while (t.length < 3) t.push(1);
  return t;
}

export const names = NAMES;
export const values = Object.keys(VALUES);

export async function createEvaluator(device) {
  if (!device) {
    const gpu = globalThis.navigator?.gpu;
    if (!gpu) throw new Error('WebGPU is not available (navigator.gpu); pass a GPUDevice to createEvaluator()');
    const adapter = await gpu.requestAdapter();
    if (!adapter) throw new Error('no WebGPU adapter available');
    device = await adapter.requestDevice({
      requiredLimits: {
        maxStorageBufferBindingSize: adapter.limits.maxStorageBufferBindingSize,
        maxBufferSize: adapter.limits.maxBufferSize,
      },
    });
  }
  const STORAGE = GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST | GPUBufferUsage.COPY_SRC;
  const module = device.createShaderModule({ code: WGSL });
  const pipeline = await device.createComputePipelineAsync({
    layout: 'auto',
    compute: { module, entryPoint: 'main' },
  });

  const fixed = {};
  for (const b of BINDINGS) {
    if (b.kind === 'heap' || b.kind === 'push') continue;
    fixed[b.binding] = device.createBuffer({ size: alignUp(Math.max(b.size, 16), 16), usage: STORAGE });
    if (b.kind === 'static') device.queue.writeBuffer(fixed[b.binding], 0, fromBase64(b.data));
  }
  const deferredTable = BINDINGS.find((b) => b.kind === 'deferred_table');
  const randomSeeds = BINDINGS.find((b) => b.kind === 'random_seeds');

  let heap = null;
  function ensureHeap(size) {
    if (heap && heap.size >= size) return;
    const grown = device.createBuffer({ size: alignUp(Math.max(size, 1 << 20), 1 << 20), usage: STORAGE });
    if (heap) {
      // keeps whatever previous dispatches wrote into node/static memory
      const encoder = device.createCommandEncoder();
      encoder.copyBufferToBuffer(heap, 0, grown, 0, STATIC_HEAP_SIZE);
      device.queue.submit([encoder.finish()]);
      heap.destroy();
    } else {
      device.queue.writeBuffer(grown, 0, fromBase64(STATIC_HEAP));
    }
    heap = grown;
  }
  ensureHeap(STATIC_HEAP_SIZE);

  async function run(inputs = {}, options = {}) {
    const threads = normalizeThreads(options.threads ?? DEFAULT_THREADS);

    // ---- named buffers go past the static part of the heap
    const placed = {};
    let cursor = alignUp(STATIC_HEAP_SIZE, BUFFER_ALIGN);
    for (const [name, data] of Object.entries(inputs)) {
      if (name in VALUES) continue;
      if (!NAMES.includes(name)) {
        throw new Error(`unknown input '${name}' (deferred names: ${NAMES.join(', ') || 'none'}; ` +
                        `values: ${Object.keys(VALUES).join(', ') || 'none'})`);
      }
      const bytes = asBytes(name, data);
      placed[name] = { offset: cursor, bytes, data };
      cursor = alignUp(cursor + Math.max(bytes.byteLength, 4), BUFFER_ALIGN);
    }
    ensureHeap(cursor);
    for (const { offset, bytes } of Object.values(placed)) device.queue.writeBuffer(heap, offset, padded(bytes));

    // ---- named values are written straight into their node field
    for (const [name, value] of Object.entries(inputs)) {
      const v = VALUES[name];
      if (!v) continue;
      const typed = new TYPED[v.type](v.count);
      if (typeof value === 'number') typed.fill(value); else typed.set(value);
      device.queue.writeBuffer(heap, v.offset, typed);
    }

    // ---- deferred entries resolve to bound buffer + offset, or null
    if (deferredTable) {
      const table = new Uint32Array(Math.max(DEFERRED_ENTRIES.length, 1) * 2);
      DEFERRED_ENTRIES.forEach(([nameIndex, offset], k) => {
        const p = placed[NAMES[nameIndex]];
        table[2 * k] = p ? p.offset + offset : 0;
      });
      device.queue.writeBuffer(fixed[deferredTable.binding], 0, table);
    }
    if (randomSeeds) {
      const seeds = new Uint32Array(4).map(() => 128 + Math.floor(Math.random() * ((1 << 30) - 128)));
      device.queue.writeBuffer(fixed[randomSeeds.binding], 0, seeds);
    }

    // ---- one dispatch per <= 65535^3 workgroup chunk (rdv_start_* offsets it)
    const groups = threads.map((t, i) => Math.ceil(t / LOCAL_SIZE[i]));
    const chunks = [];
    for (let z = 0; z < groups[2]; z += MAX_GROUPS)
      for (let y = 0; y < groups[1]; y += MAX_GROUPS)
        for (let x = 0; x < groups[0]; x += MAX_GROUPS)
          chunks.push([x, y, z]);
    const push = device.createBuffer({ size: chunks.length * UNIFORM_ALIGN, usage: STORAGE });
    const pushData = new Int32Array(chunks.length * UNIFORM_ALIGN / 4);
    chunks.forEach(([x, y, z], i) => {
      pushData.set([MAIN_NODE, 0, threads[0], threads[1], threads[2],
                    x * LOCAL_SIZE[0], y * LOCAL_SIZE[1], z * LOCAL_SIZE[2]], i * UNIFORM_ALIGN / 4);
    });
    device.queue.writeBuffer(push, 0, pushData);

    const encoder = device.createCommandEncoder();
    const pass = encoder.beginComputePass();
    pass.setPipeline(pipeline);
    chunks.forEach(([x, y, z], i) => {
      const entries = BINDINGS.map((b) => {
        if (b.kind === 'heap') return { binding: b.binding, resource: { buffer: heap } };
        if (b.kind === 'push') return { binding: b.binding, resource: { buffer: push, offset: i * UNIFORM_ALIGN, size: b.size } };
        return { binding: b.binding, resource: { buffer: fixed[b.binding] } };
      });
      pass.setBindGroup(0, device.createBindGroup({ layout: pipeline.getBindGroupLayout(0), entries }));
      pass.dispatchWorkgroups(Math.min(MAX_GROUPS, groups[0] - x), Math.min(MAX_GROUPS, groups[1] - y),
                              Math.min(MAX_GROUPS, groups[2] - z));
    });
    pass.end();

    // ---- read named buffers back into the caller's own arrays
    const readback = options.readback ?? true;
    const toRead = Object.keys(placed).filter((n) => readback === true || (Array.isArray(readback) && readback.includes(n)));
    let staging = null;
    let stagingSize = 0;
    const stagingAt = {};
    for (const name of toRead) {
      stagingAt[name] = stagingSize;
      stagingSize += alignUp(Math.max(placed[name].bytes.byteLength, 4), 4);
    }
    if (stagingSize > 0) {
      staging = device.createBuffer({ size: stagingSize, usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST });
      for (const name of toRead) {
        const p = placed[name];
        encoder.copyBufferToBuffer(heap, p.offset, staging, stagingAt[name], alignUp(Math.max(p.bytes.byteLength, 4), 4));
      }
    }
    device.queue.submit([encoder.finish()]);
    push.destroy();

    const result = {};
    if (staging) {
      await staging.mapAsync(GPUMapMode.READ);
      const mapped = new Uint8Array(staging.getMappedRange());
      for (const name of toRead) {
        const p = placed[name];
        p.bytes.set(mapped.subarray(stagingAt[name], stagingAt[name] + p.bytes.byteLength));
        result[name] = p.data;
      }
      staging.unmap();
      staging.destroy();
    } else {
      await device.queue.onSubmittedWorkDone();
    }
    return result;
  }

  // calls are serialized: each one sees the previous one's writes
  let tail = Promise.resolve();
  function evaluate(inputs, options) {
    const next = tail.then(() => run(inputs, options));
    tail = next.catch(() => {});
    return next;
  }

  function destroy() {
    heap?.destroy();
    for (const b of Object.values(fixed)) b.destroy();
  }

  return { evaluate, device, names: NAMES, values: Object.keys(VALUES), destroy };
}

let defaultEvaluator = null;

export async function evaluate(inputs = {}, options = {}) {
  if (!defaultEvaluator) defaultEvaluator = createEvaluator(options.device);
  return (await defaultEvaluator).evaluate(inputs, options);
}
